/** Logical save-stack integration for software-filtered layers and shaped text.
 * Install once after createCanvasAPI (and before recording wrappers, if used).
 */
export function installLayerEffects(K,api){
  const P=api.SKCanvas.prototype;if(P._softwareLayerHooksInstalled)return;
  Object.defineProperty(P,'_softwareLayerHooksInstalled',{value:true});
  const originalSaveLayer=P.SaveLayer,originalDispose=P.Dispose,originalShaped=P.DrawShapedText;
  const nativeInfo=(w,h)=>({width:w,height:h,colorType:K.ColorType.RGBA_F32,alphaType:K.AlphaType.Unpremul,colorSpace:K.ColorSpace.SRGB});
  const soft=p=>p?._effects?.ColorFilter?._software||p?._effects?.ImageFilter?._software;
  const rect=v=>v&&(v.Left!==undefined||Array.isArray(v)||ArrayBuffer.isView(v));
  const oldCount=Object.getOwnPropertyDescriptor(P,'SaveCount');
  if(oldCount&&!oldCount.configurable)throw new Error('Install software layer hooks before SaveCount becomes nonconfigurable.');
  Object.defineProperty(P,'SaveCount',{configurable:true,get(){this._check();return this._native.getSaveCount()+(this._softwareSaveOffset??0);}});
  P.Save=function(){this._check();const count=this.SaveCount;this._native.save();this._clipStack[count]=this._clipDirty;return count;};
  P.SaveLayer=function(...args){const record=args[0]&&(args[0].Backdrop!==undefined||args[0].Flags!==undefined)?args[0]:null,paint=record?record.Paint:rect(args[0])?args[1]:args[0];if(!soft(paint)&&!record?.Backdrop?._software){const result=record?this._native.saveLayer(paint?._native??undefined,record.Bounds?.ToArray?.()??record.Bounds??null,record.Backdrop?._native??undefined,record.Flags?.value??record.Flags??0):originalSaveLayer.apply(this,args),logical=result+(this._softwareSaveOffset??0);this._clipStack[logical]=this._clipDirty;return logical;}
    this._complex();paint?.ThrowIfDisposed();const flags=record?.Flags?.value??record?.Flags??0;const parent=this._native,bounds=Array.from(parent.getDeviceClipBounds()),width=this._owner?.Width??Math.ceil(bounds[2]),height=this._owner?.Height??Math.ceil(bounds[3]);if(!Number.isFinite(width)||!Number.isFinite(height)||width<1||height<1||width*height>67108864)throw new RangeError('Software layers require finite surface bounds.');
    const surface=api.makeEffectSurface(width,height);if(!surface)throw new Error('Software layer allocation failed.');const count=this.SaveCount,held=paint?paint.Clone():new api.SKPaint(),entry={parent,surface,layerNative:surface.getCanvas(),paint:held,width,height,count,offset:this._softwareSaveOffset??0,baseNativeSaveCount:surface.getCanvas().getSaveCount(),clipDirty:this._clipDirty,matrix:Array.from(parent.getTotalMatrix())};
    try{if(record?.Backdrop||(flags&4)){let pixels=api.readEffectPixels(parent,width,height);if(!pixels)throw new Error('Could not read software layer backdrop pixels.');if(record?.Backdrop)pixels=api.evaluateImageFilter(record.Backdrop,{pixels,width,height},entry.matrix).pixels;const image=api.makeEffectImage(pixels,width,height);try{surface.getCanvas().drawImage(image,0,0,null);}finally{image.delete();}}surface.getCanvas().concat(parent.getTotalMatrix());this._softwareLayers??=[];this._softwareLayers.push(entry);this._native=entry.layerNative;this._softwareSaveOffset=count+1-entry.baseNativeSaveCount;this._clipStack[count]=this._clipDirty;return count;}catch(e){held.Dispose();surface.dispose();throw e;}
  };
  function finishLayer(canvas){const entry=canvas._softwareLayers.pop(),{parent,surface,paint,width,height}=entry;let image=null,nativePaint=null;try{const pixels=api.readEffectPixels(surface.getCanvas(),width,height);if(!pixels)throw new Error('Could not read software layer pixels.');const result=api.applySoftwareEffects(pixels,width,height,paint,null,entry.matrix);image=api.makeEffectImage(result,width,height);nativePaint=paint._native.copy();nativePaint.setColorFilter(null);nativePaint.setImageFilter(null);nativePaint.setShader(null);const saved=parent.save();try{const inverse=K.Matrix.invert(parent.getTotalMatrix());if(!inverse)throw new RangeError('Software layers require an invertible matrix.');parent.concat(inverse);parent.drawImage(image,0,0,nativePaint);}finally{parent.restoreToCount(saved);}}
    finally{canvas._native=parent;canvas._softwareSaveOffset=entry.offset;canvas._clipDirty=entry.clipDirty;canvas._clipStack.length=entry.count;nativePaint?.delete();image?.delete();paint.Dispose();surface.dispose();}
  }
  P.Restore=function(){this._check();const layer=this._softwareLayers?.at(-1);if(layer&&this._native===layer.layerNative&&this._native.getSaveCount()===(layer.baseNativeSaveCount??1)){finishLayer(this);return;}if(this.SaveCount>1){const count=this.SaveCount-1;this._native.restore();this._clipDirty=this._clipStack[count]??this._clipDirty;this._clipStack.length=count;}};
  P.RestoreToCount=function(count){this._check();count=Math.max(1,count);while(this.SaveCount>count)this.Restore();};
  P.Dispose=function(){if(this.IsDisposed)return;while(this._softwareLayers?.length){const layer=this._softwareLayers.pop();this._native=layer.parent;layer.paint.Dispose();layer.surface.dispose();}return originalDispose.call(this);};
  if(originalShaped)P.DrawShapedText=function(text,x,y,font,paint,options={}){if(!soft(paint))return originalShaped.call(this,text,x,y,font,paint,options);this._complex();return api.renderPaintEffects(this,paint,nativePaint=>{const clean=paint.Clone();try{clean.ColorFilter=null;clean.ImageFilter=null;clean._native.delete();clean._native=nativePaint.copy();originalShaped.call(this,text,x,y,font,clean,options);}finally{clean.Dispose();}});};
}
